import {hundredthsCases} from './hundredths-content.mjs';
import {hundredthsView,startHundredths,moveHundredths,clearHundredths,chooseHundredths,supportHundredths,markHundredthsDisplayed,checkHundredths,keepHundredths,recoverHundredths,hundredthsFacts} from './hundredths-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${label}</button>`;
const moveButton=(label,step,n)=>button(label,`data-hundredths-move="${step}" ${n+step<0||n+step>100?'disabled':''}`);
const notice='<p id="hundredths-status" role="status" tabindex="-1"></p>';
function grid(n,label,active=false){return `<div class="hundredths-diagram"><div class="hundredths-picture" role="img" aria-label="${esc(label)}: ${n} of 100 equal small parts shaded in one whole square"><div class="hundredths-grid" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<n?'shaded':''}"></i>`).join('')}</div></div><p class="hundredths-count">${n} of 100 small parts shaded.</p>${active&&n>=30&&n<40?'<p class="hundredths-row-fact">3 complete rows of 10 make 30 small parts. Any remaining shaded parts are extra.</p>':''}</div>`;}
function chooser(v){return `<details class="hundredths-chooser" ${v.work?'':'open'}><summary>Choose any request</summary><div class="hundredths-requests">${hundredthsCases.map((s,i)=>`<article><h3>Request ${i+1}: ${esc(s.title)}</h3><p>${esc(s.request)}</p>${v.unreadable.some(x=>x.id===s.id)?'<p>This saved request cannot be opened here. It stays in notes; the other requests remain open.</p>':button(v.readable.some(x=>x.id===s.id)?'Return to this request':'Start this request',`data-hundredths-start="${s.id}"`)}</article>`).join('')}</div></details>`;}
function older(v){return v.status==='recovery'?`<details><summary>Earlier bridge record</summary><pre>${esc(JSON.stringify(v.root,null,2))}</pre></details>`:v.unreadable.length?`<details><summary>Earlier unreadable requests (${v.unreadable.length})</summary><pre>${esc(JSON.stringify(v.unreadable,null,2))}</pre></details>`:'';}
function responsePicture(r,s){return s.kind==='build'?grid(r.amount,'Saved selected amount'):`<p>Chosen relation: ${esc(r.choice||'none yet')}.</p><div class="hundredths-pair">${grid(s.left,'First saved fixed picture')}${grid(s.right,'Second saved fixed picture')}</div>`;}
function history(v){return `<details class="hundredths-history"><summary>Earlier checks and kept work</summary>${v.readable.map(({id,work:w})=>`<section><h3>${esc(w.source.title)}</h3><p>${esc(w.source.request)}</p>${!hundredthsCases.some(s=>s.id===id)?button('Resume this earlier request',`data-hundredths-start="${esc(id)}"`):''}${w.kept?`<article><h4>Kept draft</h4>${responsePicture(w.kept.response,w.source)}<p>Support recorded: ${esc(w.kept.support.join(', ')||'none')}.</p>${w.kept.latestCheck?`<p>Latest check copied with the draft: ${esc(w.kept.latestCheck.feedbackText)}</p>`:'<p>This draft was kept without a check.</p>'}</article>`:''}${w.checks.map(c=>`<article><h4>Earlier check ${c.id}</h4>${responsePicture(c.response,c.source)}<p>${esc(c.feedbackText)}</p><p>Practice with a supplied picture. ${c.familiar?'A familiar request.':'No earlier check for this request was recorded here.'} Prior chooser exposure remains unknown. Support before this check: ${esc(c.support.join(', ')||'none')}.</p></article>`).join('')}${!w.kept&&!w.checks.length?'<p>No checks or kept work yet.</p>':''}</section>`).join('')}</details>`;}
export function hundredthsPage(state){
 const v=hundredthsView(state),w=v.work;
 const head='<section class="hundredths-bridge" data-hundredths-root><header><a class="back" href="#numbers">Back to Number Garden</a><p class="hundredths-eyebrow">A small-part picture table</p><h1 id="hundredths-title" tabindex="-1">Hundredths Bridge</h1><p>The same whole can be redrawn as a square with smaller equal parts. Choose a request, make or compare an amount, and check together.</p></header>';
 if(v.status==='recovery')return head+'<h2>Earlier bridge work is kept</h2><p>Start a fresh bridge while keeping the entire earlier record in notes.</p>'+button('Keep earlier record and start a fresh bridge','data-hundredths-recover')+notice+older(v)+'</section>';
 let html=head+chooser(v);
 if(w){const s=w.source,c=w.checks.find(x=>x.id===w.feedbackId);html+=`<section class="hundredths-work"><h2 id="hundredths-request" tabindex="-1">${esc(s.title)}</h2><p class="hundredths-request">${esc(s.request)}</p><p class="hundredths-whole-label">${esc(s.wholeLabel)}</p><p>One row is one tenth of this whole square. One small part is one hundredth. A whole counter is a separate object, not one of these parts.</p><p class="hundredths-whole-fact">The whole grid has 10 rows of 10 small parts: 10 × 10 = 100.</p>${s.kind==='build'?`${grid(w.response.amount,'Current repair square',true)}<div class="hundredths-actions">${moveButton('Add one tenth',10,w.response.amount)}${moveButton('Remove one tenth',-10,w.response.amount)}${moveButton('Add one hundredth',1,w.response.amount)}${moveButton('Remove one hundredth',-1,w.response.amount)}${button('Clear shading','data-hundredths-clear')}</div>`:`<div class="hundredths-pair">${grid(s.left,'First fixed picture',true)}${grid(s.right,'Second fixed picture',true)}</div><p>Compare the first picture with the second.</p><div class="hundredths-actions">${[['less','less than'],['same','the same amount'],['greater','greater than']].map(([value,label])=>button(label,`data-hundredths-choice="${value}" aria-pressed="${w.response.choice===value}"`)).join('')}</div>`}<div class="hundredths-actions">${button(s.kind==='build'?'Check this amount':'Check this comparison',`data-hundredths-check ${w.nextCheckId>=Number.MAX_SAFE_INTEGER||s.kind==='compare'&&w.response.choice===null?'disabled':''}`,true)}${button('Keep this draft','data-hundredths-keep')}</div>${w.checks.length===4?'<p class="hundredths-cap">The next check replaces the oldest of four retained checks for this request. Your kept draft stays. Download notes first to keep every check.</p>':''}${w.nextCheckId>=Number.MAX_SAFE_INTEGER?'<p>This request has reached its check limit. Earlier work remains available.</p>':''}${c?`<section class="hundredths-feedback" id="hundredths-feedback" tabindex="-1"><h3>Your checked response</h3><p>${esc(c.feedbackText)}</p></section>`:''}<details class="hundredths-help" ${w.helpOpen||w.support.includes('together')?'open':''}><summary>Help if you like</summary>${button('Show an explanation','data-hundredths-help')}${button('We worked together',`data-hundredths-together aria-pressed="${w.support.includes('together')}"`)}${hearButton(s.request,'Hear this request')}${w.helpOpen?`<p id="hundredths-help-text" tabindex="-1">${esc(s.help)}</p>`:''}</details>${w.kept?'<p id="hundredths-kept-status" tabindex="-1">A copy is kept in earlier checks and kept work. Later edits need another Keep.</p>':''}</section>`;}
 if(v.status==='ready'){html+=history(v)+older(v);if(v.unreadable.length)html+='<p>Keep the whole earlier record in notes and start a fresh bridge if needed.</p>'+button('Keep earlier record and start a fresh bridge','data-hundredths-recover');if(Object.hasOwn(v.root,'recovered'))html+=`<details><summary>Whole earlier bridge kept for recovery</summary><pre>${esc(JSON.stringify(v.root.recovered,null,2))}</pre></details>`;}
 return html+notice+'<p><a href="#notes">Grown-up notes and download</a> · <a href="#numbers/tenths">Visit Tenths Table</a></p><details><summary>For grown-ups</summary><p>These supplied pictures and requests are guided practice. They do not establish independent decimal writing, comparison fluency or mastery. Chooser notation can have been seen without a saved case, so prior exposure is unknown.</p></details></section>';
}
export function hundredthsEntry(){return '<section class="hundredths-entry"><h2>One whole, smaller parts</h2><p>Make tenths and hundredths on a square picture, then compare amounts.</p><a class="secondary" href="#numbers/hundredths">Visit Hundredths Bridge</a></section>';}
export function hundredthsNotes(state){if(!Object.hasOwn(state,'hundredthsBridge'))return '';const v=hundredthsView(state);return `<details class="panel"><summary>Hundredths Bridge: supplied pictured practice</summary><p>Each request retains its original source. Chooser notation exposure is unknown. Checks and support are practice records, not independent decimal knowledge.</p>${v.status==='recovery'?older(v):history(v)+older(v)}<pre>${esc(JSON.stringify(state.hundredthsBridge,null,2))}</pre></details>`;}
export function bindHundredths(state,{save,render,focus,canExport,exposeFacts}={}){
 const root=document.querySelector('[data-hundredths-root]');if(!root)return;
 const preview=candidate=>{const shown=structuredClone(candidate);markHundredthsDisplayed(shown);const pairs=hundredthsFacts(shown);if(pairs.length)exposeFacts?.(pairs,shown);return canExport?.(shown)??true;};
 const displayed=markHundredthsDisplayed(state,preview);if(displayed)save?.();
 const pairs=hundredthsFacts(state),factsFit=!pairs.length||preview(state);
 if(pairs.length&&factsFit){exposeFacts?.(pairs);save?.();}
 const work=hundredthsView(state).work,feedback=work?.checks.find(c=>c.id===work.feedbackId);
 if(work&&(!work.sourceShown||feedback&&!feedback.feedbackShown||!factsFit))root.querySelector('#hundredths-status').textContent='This newly shown picture could not be recorded safely. Earlier work is unchanged. Download notes and start a separate explorer before more work.';
 const status=message=>{const n=document.querySelector('#hundredths-status');if(n){n.textContent=message;focus?.('#hundredths-status');}};
 const refresh=target=>{save?.();render?.();focus?.(target);};
 const refreshMove=step=>{save?.();render?.();const forward=`[data-hundredths-move="${step}"]`,reverse=`[data-hundredths-move="${-step}"]`,usable=selector=>{const control=document.querySelector(selector);return control&&!control.disabled;};focus?.(usable(forward)?forward:usable(reverse)?reverse:'#hundredths-request');};
 const refusal='This change could not be saved safely. Earlier work is unchanged. Download it from Grown-up notes, then start a separate explorer if needed.';
 root.querySelectorAll('[data-hundredths-start]').forEach(b=>b.addEventListener('click',()=>{if(startHundredths(state,b.dataset.hundredthsStart,preview))refresh('#hundredths-request');else status(refusal);}));
 root.querySelectorAll('[data-hundredths-move]').forEach(b=>b.addEventListener('click',()=>{if(moveHundredths(state,Number(b.dataset.hundredthsMove),preview))refreshMove(Number(b.dataset.hundredthsMove));else status(refusal);}));
 root.querySelector('[data-hundredths-clear]')?.addEventListener('click',()=>{if(clearHundredths(state,preview))refresh('[data-hundredths-clear]');else status(refusal);});
 root.querySelectorAll('[data-hundredths-choice]').forEach(b=>b.addEventListener('click',()=>{if(chooseHundredths(state,b.dataset.hundredthsChoice,preview))refresh(`[data-hundredths-choice="${b.dataset.hundredthsChoice}"]`);else status(refusal);}));
 root.querySelector('[data-hundredths-check]')?.addEventListener('click',()=>{if(checkHundredths(state,preview))refresh('#hundredths-feedback');else status(refusal);});
 root.querySelector('[data-hundredths-keep]')?.addEventListener('click',()=>{if(keepHundredths(state,preview))refresh('#hundredths-kept-status');else status(refusal);});
 root.querySelector('[data-hundredths-help]')?.addEventListener('click',()=>{if(supportHundredths(state,'help',preview))refresh('#hundredths-help-text');else status(refusal);});
 root.querySelector('[data-hundredths-together]')?.addEventListener('click',()=>{if(supportHundredths(state,'together',preview))refresh('[data-hundredths-together]');else status(refusal);});
 root.querySelector('[data-hundredths-recover]')?.addEventListener('click',()=>{if(recoverHundredths(state,preview))refresh('#hundredths-request');else status(refusal);});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(supportHundredths(state,'narrationRequested',preview))save?.();},{capture:true}));
}
